	xy[0][0] = (s32)(p0->x * 16.0f) - 0x8000 - 0x1400;
	xy[0][1] = (s32)(p0->y * 16.0f) - 0x8000 - 0xe00;
	xy[1][0] = (s32)(p1->x * 16.0f) - 0x8000 - 0x1400;
	xy[1][1] = (s32)(p1->y * 16.0f) - 0x8000 - 0xe00;
